/* Auto-generated by build-i18n.js — native translations for the featured breakout. */
(function(){var B=window.BREAKOUT;if(!B)return;var T={"es":{"UI":{"sect.clues":"🔍 Las pruebas","sect.cluesHint":"Toca cada prueba para leerla. Puedes abrirlas de nuevo cuando quieras.","sect.locks":"🔒 Los candados","sect.locksHint":"Abre cada candado usando solo las pruebas de arriba.","crumb.teacher":"‹ Inicio para docentes","crumb.suite":"Breakouts de pensamiento crítico de Ciencias","ui.reset":"↺ Reiniciar","ui.check":"Comprobar","ui.gotit":"Entendido","ui.playagain":"Jugar otra vez","ui.solved":"🔓 ¡Abierto!","ui.pcount":"{n} de {total} candados abiertos","ui.wordph":"Escribe tu respuesta","ui.clear":"borrar","fb.digit":"Ese número no coincide con las pruebas. Revísalo otra vez.","fb.word":"Busca en las pruebas la palabra que encaja.","fb.mc":"Esa no la respaldan las pruebas. Míralas otra vez.","fb.multiExtra":"Una de tus opciones no es una prueba sólida. Sólida significa hechos que las pruebas realmente demuestran sobre las fuerzas.","fb.multiMissing":"Te falta una prueba sólida. Encuéntralas todas.","fb.seq":"Ese orden no coincide con cómo se transfiere la energía. Inténtalo de nuevo.","footer.privacy":"Privacidad y cumplimiento","footer.disclaimer":"Alineado con los Conocimientos y Destrezas Esenciales de Texas para Ciencias de 2021 (§112.26, 6.º grado). Paráfrasis de buena fe; confírmalo antes de adoptarlo.","header.eyebrow":"Breakout de pensamiento crítico de Ciencias · 6.º grado","header.h1":"Rescate del barco de carga","header.sub":"El carguero TEKS Voyager está atascado en el Puerto de Houston. Va peligrosamente bajo en el agua, una caja de la cubierta se desliza sin parar y la grúa de carga pierde energía. Tú eres el ingeniero del puerto. Lee las pruebas, abre los cuatro candados y autoriza al barco a zarpar.","brief.label":"⚓ Tu misión","brief.h":"Autoriza al Voyager a zarpar","brief.p":"El supervisor del muelle te llama por radio: <b>“No deja de hundirse, una caja se deslizó por la cubierta y la grúa se apagó de golpe.”</b> Cada problema tiene una razón científica escondida en las pruebas: densidad, fuerzas y energía. Abre cada prueba, analiza qué demuestra en realidad y abre los cuatro candados para enviar al Voyager sano y salvo al mar.","footer.text":"Breakouts de pensamiento crítico de Ciencias · Funciona por completo en tu navegador: sin cuentas, sin recopilar datos.","win.stamp":"AUTORIZADO A ZARPAR ✓","win.h":"¡El Voyager zarpa!","win.p":"Usaste la densidad para explicar por qué flota un barco de acero, demostraste que las fuerzas sobre la caja estaban equilibradas, nombraste la Tercera Ley de Newton y seguiste la energía de la grúa sin perder ni un julio. Así es exactamente como los ingenieros marinos mantienen seguros los barcos reales."},"CONTENT":{"clues":[{"id":"c1","ico":"⚖️","nm":"La densidad manda","title":"La densidad decide quién flota","body":"Densidad = masa ÷ volumen. Un objeto flota en un fluido cuando su densidad <b>total</b> es <b>menor</b> que la del fluido. El acero es mucho más denso que el agua: una barra maciza de acero se hunde. Pero el casco hueco de un barco reparte la misma masa en un volumen enorme, así que la densidad total del barco baja por debajo de la del agua, y flota."},{"id":"c2","ico":"🚢","nm":"Muy bajo en el agua","title":"Por qué el Voyager va tan bajo","body":"Cada caja que se carga añade <b>masa</b> pero no <b>volumen</b> al casco. Más masa en el mismo volumen empuja la densidad total del barco hacia la del agua. Si cargas más allá de la línea de carga pintada, la densidad total supera la del agua: entonces el barco deja de flotar y empieza a hundirse."},{"id":"c3","ico":"🧲","nm":"La caja que se desliza","title":"La caja que se deslizó","body":"Una caja descansa sobre la cubierta plana. La gravedad la tira hacia abajo; la <b>fuerza normal</b> de la cubierta empuja hacia arriba con la misma intensidad; la <b>fricción</b> la sujeta ante un pequeño empujón. Cuando todas las fuerzas sobre la caja suman <b>cero</b>, la fuerza neta es cero y su movimiento no cambia: eso es estar <b>equilibrada</b>. Una ola añade un empujón extra hacia el lado, la fuerza neta deja de ser cero, y la caja se desliza."},{"id":"c4","ico":"🔁","nm":"Empujar hacia atrás","title":"El empuje de la hélice","body":"<b>Tercera Ley</b> de Newton: para cada fuerza hay una fuerza igual y opuesta sobre el <b>otro</b> objeto. La hélice empuja el agua <b>hacia atrás</b>; el agua empuja el barco <b>hacia adelante</b>. Las dos fuerzas son iguales en intensidad y opuestas en dirección, pero actúan sobre <b>objetos diferentes</b>, así que no se cancelan, y el barco avanza."},{"id":"c5","ico":"⚡","nm":"La energía de la grúa","title":"Adónde va la energía de la grúa","body":"La grúa funciona con <b>energía eléctrica</b> del muelle. Levanta una caja a lo alto y almacena <b>energía potencial gravitatoria</b>. Cuando la caja baja, esa energía almacenada se transforma en <b>energía cinética</b> de movimiento. La energía nunca se crea ni se destruye: solo se transfiere y cambia de forma. Síguela en orden y no se pierde nada."},{"id":"c6","ico":"🐙","nm":"Dato de un buzo","title":"El dato favorito de un buzo del puerto","body":"El pulpo gigante del Pacífico tiene <b>tres corazones</b> y sangre azul con cobre, y puede pasar por cualquier hueco más grande que su pico. A los buzos del puerto les encanta verlo cerca de los pilotes. Es un dato verdadero y asombroso, pero no te dice nada sobre cargar o navegar el Voyager."}],"locks":[{"id":"L1","type":"seq","color":"#f0a316","title":"Sigue la energía de la grúa","q":"Pon la energía de la grúa en el orden en que se transforma mientras levanta y luego baja una caja. Toca los botones en orden.","pads":[{"k":"pot","e":"⬆️ Potencial","c":"#1aa3b8"},{"k":"elec","e":"🔌 Eléctrica","c":"#f0a316"},{"k":"kin","e":"⬇️ Cinética","c":"#2f6fe0"}],"answer":["elec","pot","kin"],"reason":"La energía eléctrica levanta la caja (almacenando energía potencial), y luego al bajarla se libera energía cinética. Seguir las transferencias de energía en orden muestra que la energía se conserva, no se pierde."},{"id":"L2","type":"mc","color":"#0a6b52","title":"Por qué flota el barco de acero","q":"Una barra maciza de acero se hunde, pero el Voyager de acero flota. ¿Qué explicación respaldan las pruebas?","options":["El barco simplemente pesa menos que la barra.","El casco hueco reparte la masa del barco en un gran volumen, así que su densidad total es menor que la del agua.","El agua empuja más fuerte sobre los objetos grandes que sobre los pequeños."],"answerIndex":1,"reason":"La densidad compara la masa con el volumen. Dar al acero forma de casco hueco aumenta su volumen, lo que baja la densidad total por debajo de la del agua, y eso es lo que hace que flote."},{"id":"L3","type":"multi","color":"#2f6fe0","title":"¿Equilibradas o no?","q":"Antes de que llegara la ola, la caja estaba perfectamente quieta. Marca SOLO las pruebas sólidas de que las fuerzas sobre la caja estaban EQUILIBRADAS (fuerza neta = cero). Deja fuera el dato verdadero pero fuera de tema.","items":[{"t":"La gravedad que tira hacia abajo y la fuerza normal de la cubierta que empuja hacia arriba son iguales en intensidad.","strong":true},{"t":"La fricción cancela un empujón suave hacia el lado, así que la caja no se mueve.","strong":true},{"t":"La caja sigue quieta: su movimiento no cambia.","strong":true},{"t":"Un pulpo gigante del Pacífico tiene tres corazones y sangre azul.","strong":false}],"reason":"Las fuerzas equilibradas suman cero, así que el movimiento de un objeto no cambia. Una prueba sólida es solo la que muestra que la fuerza neta es cero; el dato del pulpo es verdadero pero irrelevante."},{"id":"L4","type":"word","color":"#e0533a","title":"Nombra la ley","q":"La hélice empuja el agua hacia atrás y el agua empuja el barco hacia adelante: igual intensidad, dirección opuesta, sobre objetos diferentes. ¿Cuál de las leyes de Newton es esta? Escribe la palabra del número (por ejemplo, “primera”).","answer":["tercera","3ra","tercera ley","tercera ley de newton","ley de newton tercera","acción-reacción","accion-reaccion","acción reacción","accion reaccion","third","3rd","newton's third","newtons third","third law","newton's third law","action-reaction","action reaction"],"reason":"Esta es la Tercera Ley de Newton. Los pares de fuerzas de la Tercera Ley son iguales y opuestos pero actúan sobre objetos diferentes, así que nunca se cancelan, y por eso justamente el barco avanza."}]}},"vi":{"UI":{"sect.clues":"🔍 Bằng Chứng","sect.cluesHint":"Chạm vào từng bằng chứng để đọc. (Bạn có thể mở lại bất cứ lúc nào.)","sect.locks":"🔒 Các Ổ Khóa","sect.locksHint":"Chỉ dùng các bằng chứng ở trên để mở từng ổ khóa.","crumb.teacher":"‹ Khởi động cho giáo viên","crumb.suite":"Các Breakout Tư Duy Phản Biện Khoa Học","ui.reset":"↺ Bắt đầu lại","ui.check":"Kiểm tra","ui.gotit":"Hiểu rồi","ui.playagain":"Chơi Lại","ui.solved":"🔓 Đã Mở!","ui.pcount":"Đã mở {n} trên {total} ổ khóa","ui.wordph":"Nhập câu trả lời của bạn","ui.clear":"xóa","fb.digit":"Con số đó không khớp với bằng chứng. Hãy kiểm tra lại.","fb.word":"Hãy xem bằng chứng để tìm từ phù hợp.","fb.mc":"Đáp án đó không được bằng chứng ủng hộ. Hãy xem lại.","fb.multiExtra":"Một lựa chọn không phải là bằng chứng vững chắc. Bằng chứng vững chắc là những sự thật mà bằng chứng thực sự chứng minh về các lực.","fb.multiMissing":"Bạn còn thiếu một bằng chứng vững chắc. Hãy tìm cho đủ.","fb.seq":"Thứ tự đó không khớp với cách năng lượng truyền đi. Hãy thử lại.","footer.privacy":"Quyền riêng tư & tuân thủ","footer.disclaimer":"Phù hợp với Kiến Thức và Kỹ Năng Thiết Yếu về Khoa Học của Texas năm 2021 (§112.26, Lớp 6). Diễn giải với thiện chí; hãy xác nhận trước khi áp dụng.","header.eyebrow":"Breakout Tư Duy Phản Biện Khoa Học · Lớp 6","header.h1":"Giải Cứu Tàu Hàng","header.sub":"Tàu chở hàng TEKS Voyager bị kẹt tại Cảng Houston. Con tàu chìm thấp một cách nguy hiểm, một thùng hàng trên boong cứ trượt đi, và cần cẩu bốc dỡ bị mất điện. Bạn là kỹ sư cảng. Hãy đọc bằng chứng, mở cả bốn ổ khóa, và cho phép con tàu ra khơi.","brief.label":"⚓ Nhiệm Vụ","brief.h":"Cho phép tàu Voyager ra khơi","brief.p":"Người giám sát bến tàu gọi bộ đàm cho bạn: <b>“Con tàu cứ chìm thấp mãi, một thùng hàng trượt ngang boong, và cần cẩu bị ngắt điện.”</b> Mỗi vấn đề đều có một lý do khoa học ẩn trong bằng chứng — khối lượng riêng, lực và năng lượng. Hãy mở từng bằng chứng, cân nhắc điều nó thực sự chứng minh, và mở cả bốn ổ khóa để đưa tàu Voyager ra khơi an toàn.","footer.text":"Breakout Tư Duy Phản Biện Khoa Học · Chạy hoàn toàn trên trình duyệt của bạn — không đăng nhập, không thu thập dữ liệu.","win.stamp":"ĐƯỢC PHÉP RA KHƠI ✓","win.h":"Tàu Voyager ra khơi!","win.p":"Bạn đã dùng khối lượng riêng để giải thích vì sao con tàu thép nổi, chứng minh các lực trên thùng hàng cân bằng, gọi tên Định Luật Ba của Newton, và lần theo năng lượng của cần cẩu mà không mất một jun nào. Đó chính là cách các kỹ sư hàng hải giữ an toàn cho tàu thật."},"CONTENT":{"clues":[{"id":"c1","ico":"⚖️","nm":"Khối Lượng Riêng Quyết Định","title":"Khối Lượng Riêng Quyết Định Ai Nổi","body":"Khối lượng riêng = khối lượng ÷ thể tích. Một vật nổi trong chất lỏng khi khối lượng riêng <b>tổng thể</b> của nó <b>nhỏ hơn</b> khối lượng riêng của chất lỏng. Thép đặc hơn nước rất nhiều — một thanh thép đặc sẽ chìm. Nhưng thân tàu rỗng trải cùng khối lượng đó trên một thể tích khổng lồ, nên khối lượng riêng tổng thể của con tàu giảm xuống dưới nước, và nó nổi."},{"id":"c2","ico":"🚢","nm":"Chìm Quá Thấp","title":"Vì Sao Tàu Voyager Chìm Thấp","body":"Mỗi thùng hàng được xếp lên làm tăng <b>khối lượng</b> nhưng không tăng <b>thể tích</b> của thân tàu. Nhiều khối lượng hơn trong cùng một thể tích đẩy khối lượng riêng tổng thể của con tàu tiến gần bằng nước. Xếp quá vạch mớn nước được sơn và khối lượng riêng tổng thể vượt qua nước — khi đó con tàu ngừng nổi và bắt đầu chìm."},{"id":"c3","ico":"🧲","nm":"Thùng Hàng Trượt","title":"Thùng Hàng Đã Trượt","body":"Một thùng hàng nằm trên boong phẳng. Trọng lực kéo nó xuống; <b>lực pháp tuyến</b> của boong đẩy lên với độ lớn bằng nhau; <b>ma sát</b> giữ nó lại trước một cú đẩy nhẹ. Khi tất cả các lực tác dụng lên thùng hàng cộng lại bằng <b>không</b>, hợp lực bằng không và chuyển động của nó không thay đổi — đó là <b>cân bằng</b>. Một con sóng thêm một lực đẩy ngang nữa, hợp lực không còn bằng không, và thùng hàng trượt đi."},{"id":"c4","ico":"🔁","nm":"Đẩy Ngược Lại","title":"Cú Đẩy Của Chân Vịt","body":"<b>Định Luật Ba</b> của Newton: với mỗi lực đều có một lực có độ lớn bằng nhau và ngược chiều tác dụng lên vật <b>kia</b>. Chân vịt đẩy nước <b>về phía sau</b>; nước đẩy con tàu <b>về phía trước</b>. Hai lực này có độ lớn bằng nhau và ngược chiều, nhưng chúng tác dụng lên <b>hai vật khác nhau</b>, nên chúng không triệt tiêu nhau — và con tàu tiến lên."},{"id":"c5","ico":"⚡","nm":"Năng Lượng Của Cần Cẩu","title":"Năng Lượng Của Cần Cẩu Đi Về Đâu","body":"Cần cẩu chạy bằng <b>năng lượng điện</b> từ bến tàu. Nó nâng thùng hàng lên cao, tích trữ <b>thế năng hấp dẫn</b>. Khi hạ thùng hàng xuống, năng lượng tích trữ đó chuyển thành <b>động năng</b> của chuyển động. Năng lượng không bao giờ được tạo ra hay mất đi — nó chỉ truyền đi và đổi dạng. Hãy lần theo nó đúng thứ tự và sẽ không mất chút nào."},{"id":"c6","ico":"🐙","nm":"Sự Thật Của Thợ Lặn","title":"Sự Thật Ưa Thích Của Thợ Lặn Cảng","body":"Bạch tuộc khổng lồ Thái Bình Dương có <b>ba trái tim</b> và máu màu xanh dựa trên đồng, và có thể chui qua bất kỳ khe hở nào lớn hơn cái mỏ của nó. Các thợ lặn cảng rất thích bắt gặp một con gần cọc cầu tàu. Đây là một sự thật đúng và tuyệt vời — nhưng nó không cho bạn biết gì về việc xếp hàng hay điều khiển tàu Voyager."}],"locks":[{"id":"L1","type":"seq","color":"#f0a316","title":"Lần Theo Năng Lượng Của Cần Cẩu","q":"Hãy sắp xếp năng lượng của cần cẩu theo thứ tự nó chuyển hóa khi nâng rồi hạ một thùng hàng. Chạm vào các ô theo thứ tự.","pads":[{"k":"pot","e":"⬆️ Thế năng","c":"#1aa3b8"},{"k":"elec","e":"🔌 Điện năng","c":"#f0a316"},{"k":"kin","e":"⬇️ Động năng","c":"#2f6fe0"}],"answer":["elec","pot","kin"],"reason":"Năng lượng điện nâng thùng hàng lên (tích trữ thế năng), rồi hạ nó xuống giải phóng động năng. Lần theo sự truyền năng lượng đúng thứ tự cho thấy năng lượng được bảo toàn, không mất đi."},{"id":"L2","type":"mc","color":"#0a6b52","title":"Vì Sao Tàu Thép Nổi","q":"Một thanh thép đặc thì chìm, thế mà tàu Voyager bằng thép lại nổi. Bằng chứng ủng hộ lời giải thích nào?","options":["Con tàu đơn giản là nhẹ hơn thanh thép.","Thân tàu rỗng trải khối lượng của con tàu trên một thể tích lớn, nên khối lượng riêng tổng thể của nó nhỏ hơn nước.","Nước đẩy mạnh hơn lên vật lớn so với vật nhỏ."],"answerIndex":1,"reason":"Khối lượng riêng so sánh khối lượng với thể tích. Tạo hình thép thành thân tàu rỗng làm tăng thể tích, khiến khối lượng riêng tổng thể nhỏ hơn nước — và đó là điều làm nó nổi."},{"id":"L3","type":"multi","color":"#2f6fe0","title":"Cân Bằng Hay Không?","q":"Trước khi sóng ập tới, thùng hàng nằm hoàn toàn yên. CHỈ chọn những bằng chứng vững chắc cho thấy các lực trên thùng hàng đã CÂN BẰNG (hợp lực = không). Bỏ qua sự thật đúng nhưng lạc đề.","items":[{"t":"Trọng lực kéo xuống và lực pháp tuyến của boong đẩy lên có độ lớn bằng nhau.","strong":true},{"t":"Ma sát triệt tiêu một cú đẩy ngang nhẹ, nên thùng hàng không nhúc nhích.","strong":true},{"t":"Thùng hàng nằm yên — chuyển động của nó không thay đổi.","strong":true},{"t":"Bạch tuộc khổng lồ Thái Bình Dương có ba trái tim và máu màu xanh.","strong":false}],"reason":"Các lực cân bằng cộng lại bằng không, nên chuyển động của vật không thay đổi. Bằng chứng vững chắc chỉ là những gì cho thấy hợp lực bằng không — sự thật về bạch tuộc là đúng nhưng không liên quan."},{"id":"L4","type":"word","color":"#e0533a","title":"Gọi Tên Định Luật","q":"Chân vịt đẩy nước về phía sau và nước đẩy con tàu về phía trước — độ lớn bằng nhau, ngược chiều, trên hai vật khác nhau. Đây là định luật nào của Newton? Hãy nhập từ chỉ số (ví dụ: “thứ nhất”).","answer":["thứ ba","định luật ba","định luật ba của newton","định luật thứ ba của newton","định luật iii","phản lực","tác dụng-phản tác dụng","ba","third","3rd","newton's third","newtons third","third law","newton's third law","action-reaction","action reaction","tercera"],"reason":"Đây là Định Luật Ba của Newton. Cặp lực theo Định Luật Ba có độ lớn bằng nhau và ngược chiều nhưng tác dụng lên hai vật khác nhau, nên chúng không bao giờ triệt tiêu nhau — đó chính là lý do con tàu tiến về phía trước."}]}},"ar":{"UI":{"sect.clues":"🔍 الأدلّة","sect.cluesHint":"انقر على كل دليل لقراءته. يمكنك فتحها مرة أخرى في أي وقت.","sect.locks":"🔒 الأقفال","sect.locksHint":"استخدم الأدلّة أعلاه فقط لفتح كل قفل.","crumb.teacher":"‹ إطلاق المعلّم","crumb.suite":"بريك آوت التفكير الناقد في العلوم","ui.reset":"↺ ابدأ من جديد","ui.check":"تحقّق","ui.gotit":"فهمت","ui.playagain":"العب مرة أخرى","ui.solved":"🔓 مفتوح!","ui.pcount":"{n} من {total} أقفال مفتوحة","ui.wordph":"اكتب إجابتك","ui.clear":"مسح","fb.digit":"هذا الرقم لا يطابق الأدلّة. تحقّق مرة أخرى.","fb.word":"انظر إلى الأدلّة لتجد الكلمة المناسبة.","fb.mc":"هذا الخيار لا تدعمه الأدلّة. انظر مرة أخرى.","fb.multiExtra":"أحد اختياراتك ليس دليلاً قوياً. الدليل القوي هو حقائق تُثبتها الأدلّة فعلاً عن القوى.","fb.multiMissing":"ينقصك دليل قوي واحد. اعثر عليها كلها.","fb.seq":"هذا الترتيب لا يطابق كيفية انتقال الطاقة. حاول مرة أخرى.","footer.privacy":"الخصوصية والامتثال","footer.disclaimer":"متوافق مع المعايير الأساسية للمعرفة والمهارات في العلوم بولاية تكساس لعام 2021 (§112.26، الصف السادس). إعادة صياغة بحسن نيّة؛ تأكّد منها قبل الاعتماد.","header.eyebrow":"بريك آوت التفكير الناقد في العلوم · الصف السادس","header.h1":"إنقاذ سفينة الشحن","header.sub":"علِقت الباخرة «TEKS Voyager» في ميناء هيوستن. إنها تغوص في الماء بشكل خطير، وصندوق على سطحها لا يتوقّف عن الانزلاق، ورافعة التحميل تفقد الطاقة. أنت مهندس الميناء. اقرأ الأدلّة، وافتح الأقفال الأربعة كلها، وأذَن للسفينة بالإبحار.","brief.label":"⚓ ملخّص المهمّة","brief.h":"أذَن للسفينة Voyager بالإبحار","brief.p":"يتّصل بك مشرف الرصيف عبر اللاسلكي: <b>«إنها لا تتوقّف عن الغوص، وصندوق انزلق عبر السطح، والرافعة انقطعت طاقتها.»</b> لكل مشكلة سبب علمي مختبئ في الأدلّة — الكثافة، والقوى، والطاقة. افتح كل دليل، وزِن ما يُثبته فعلاً، وافتح الأقفال الأربعة كلها لإرسال السفينة Voyager بأمان إلى البحر.","footer.text":"بريك آوت التفكير الناقد في العلوم · يعمل بالكامل داخل متصفّحك — بلا تسجيل دخول، ولا جمع بيانات.","win.stamp":"أُذِن لها بالإبحار ✓","win.h":"السفينة Voyager تبحر!","win.p":"استخدمت الكثافة لتشرح لماذا تطفو سفينة فولاذية، وأثبتّ أن القوى على الصندوق كانت متوازنة، وسمّيت قانون نيوتن الثالث، وتتبّعت طاقة الرافعة دون أن تفقد جولاً واحداً. هكذا بالضبط يحافظ مهندسو البحرية على سلامة السفن الحقيقية."},"CONTENT":{"clues":[{"id":"c1","ico":"⚖️","nm":"الكثافة تقرّر","title":"الكثافة تقرّر مَن يطفو","body":"الكثافة = الكتلة ÷ الحجم. يطفو الجسم في مائع عندما تكون كثافته <b>الإجمالية</b> <b>أقل</b> من كثافة المائع. الفولاذ أكثف بكثير من الماء — فقضيب فولاذ صلب يغرق. لكن هيكل السفينة المجوّف يوزّع الكتلة نفسها على حجم هائل، فتنخفض الكثافة الإجمالية للسفينة دون كثافة الماء، فتطفو."},{"id":"c2","ico":"🚢","nm":"تغوص كثيراً","title":"لماذا تغوص السفينة Voyager","body":"كل صندوق يُحمّل يضيف <b>كتلة</b> لكن لا يضيف <b>حجماً</b> للهيكل. المزيد من الكتلة في الحجم نفسه يدفع كثافة السفينة الإجمالية نحو كثافة الماء. حمّلها أبعد من خط التحميل المرسوم، فتتجاوز الكثافة الإجمالية كثافة الماء — عندها تتوقّف السفينة عن الطفو وتبدأ بالغرق."},{"id":"c3","ico":"🧲","nm":"الصندوق المنزلق","title":"الصندوق الذي انزلق","body":"يرتكز صندوق على السطح المستوي. الجاذبية تسحبه للأسفل؛ و<b>القوة العمودية</b> للسطح تدفعه للأعلى بمقدار مساوٍ؛ و<b>الاحتكاك</b> يثبّته ضد دفعة خفيفة. عندما يكون مجموع كل القوى على الصندوق <b>صفراً</b>، تكون القوة المحصّلة صفراً ولا تتغيّر حركته — وهذا معنى أنها <b>متوازنة</b>. تضيف موجة دفعة جانبية إضافية واحدة، فلا تبقى القوة المحصّلة صفراً، فينزلق الصندوق."},{"id":"c4","ico":"🔁","nm":"دفعة معاكسة","title":"دفعة المروحة","body":"<b>قانون نيوتن الثالث</b>: لكل قوة قوة مساوية ومعاكسة على الجسم <b>الآخر</b>. المروحة تدفع الماء <b>للخلف</b>؛ والماء يدفع السفينة <b>للأمام</b>. القوّتان متساويتان في المقدار ومتعاكستان في الاتجاه، لكنهما تؤثّران على <b>جسمين مختلفين</b>، فلا تُلغي إحداهما الأخرى — فتتقدّم السفينة."},{"id":"c5","ico":"⚡","nm":"طاقة الرافعة","title":"إلى أين تذهب طاقة الرافعة","body":"تعمل الرافعة على <b>الطاقة الكهربائية</b> من الرصيف. ترفع صندوقاً عالياً، فتخزّن <b>طاقة وضع جاذبية</b>. وعندما يُنزَل الصندوق، تتحوّل تلك الطاقة المخزّنة إلى <b>طاقة حركية</b>. الطاقة لا تُخلَق ولا تُفنى — بل تنتقل وتتغيّر صورتها فقط. تتبّعها بالترتيب فلا يضيع منها شيء."},{"id":"c6","ico":"🐙","nm":"معلومة الغطّاس","title":"معلومة يحبّها غطّاس الميناء","body":"الأخطبوط الهادئ العملاق له <b>ثلاثة قلوب</b> ودم أزرق أساسه النحاس، ويستطيع أن يمرّ عبر أي فتحة أكبر من منقاره. يحبّ غطّاسو الميناء رؤية واحد منها قرب الركائز. إنها حقيقة صحيحة ومدهشة — لكنها لا تخبرك بشيء عن تحميل السفينة Voyager أو إبحارها."}],"locks":[{"id":"L1","type":"seq","color":"#f0a316","title":"تتبّع طاقة الرافعة","q":"رتّب طاقة الرافعة بالترتيب الذي تتحوّل به وهي ترفع صندوقاً ثم تُنزله. انقر على الأزرار بالترتيب.","pads":[{"k":"pot","e":"⬆️ وضع","c":"#1aa3b8"},{"k":"elec","e":"🔌 كهربائية","c":"#f0a316"},{"k":"kin","e":"⬇️ حركية","c":"#2f6fe0"}],"answer":["elec","pot","kin"],"reason":"الطاقة الكهربائية ترفع الصندوق (فتخزّن طاقة وضع)، ثم إنزاله يُطلق طاقة حركية. تتبّع انتقالات الطاقة بالترتيب يُظهر أن الطاقة محفوظة، لا مفقودة."},{"id":"L2","type":"mc","color":"#0a6b52","title":"لماذا تطفو السفينة الفولاذية","q":"قضيب فولاذ صلب يغرق، ومع ذلك تطفو السفينة الفولاذية Voyager. أي تفسير تدعمه الأدلّة؟","options":["السفينة ببساطة أخفّ من القضيب.","الهيكل المجوّف يوزّع كتلة السفينة على حجم كبير، فتصبح كثافتها الإجمالية أقل من كثافة الماء.","الماء يدفع الأجسام الكبيرة بقوة أكبر من الأجسام الصغيرة."],"answerIndex":1,"reason":"الكثافة تقارن الكتلة بالحجم. تشكيل الفولاذ في هيكل مجوّف يزيد حجمه، فتنخفض الكثافة الإجمالية دون كثافة الماء — وهذا ما يجعله يطفو."},{"id":"L3","type":"multi","color":"#2f6fe0","title":"متوازنة أم لا؟","q":"قبل أن تصطدم الموجة، كان الصندوق ساكناً تماماً. اختر <b>فقط</b> الأدلّة القوية على أن القوى على الصندوق كانت <b>متوازنة</b> (القوة المحصّلة = صفر). اترك الحقيقة الصحيحة لكن الخارجة عن الموضوع.","items":[{"t":"الجاذبية تسحب للأسفل والقوة العمودية للسطح تدفع للأعلى بمقدار متساوٍ.","strong":true},{"t":"الاحتكاك يُلغي دفعة جانبية خفيفة، فلا يتحرّك الصندوق.","strong":true},{"t":"يبقى الصندوق ساكناً — حركته لا تتغيّر.","strong":true},{"t":"الأخطبوط الهادئ العملاق له ثلاثة قلوب ودم أزرق.","strong":false}],"reason":"القوى المتوازنة يكون مجموعها صفراً، فلا تتغيّر حركة الجسم. الدليل القوي هو فقط ما يُظهر أن القوة المحصّلة صفر — أما معلومة الأخطبوط فصحيحة لكنها غير ذات صلة."},{"id":"L4","type":"word","color":"#e0533a","title":"سمِّ القانون","q":"المروحة تدفع الماء للخلف والماء يدفع السفينة للأمام — بمقدار متساوٍ، واتجاه معاكس، وعلى جسمين مختلفين. أي من قوانين نيوتن هذا؟ اكتب رقمه بالكلمات (مثلاً: «الأول»).","answer":["الثالث","third","3rd","newton's third","newtons third","third law","newton's third law","action-reaction","action reaction","tercera"],"reason":"هذا قانون نيوتن الثالث. أزواج قوى القانون الثالث متساوية ومتعاكسة لكنها تؤثّر على جسمين مختلفين، فلا تُلغي إحداهما الأخرى — وهذا بالضبط سبب تقدّم السفينة للأمام."}]}},"hi":{"UI":{"sect.clues":"🔍 सबूत","sect.cluesHint":"हर सबूत को पढ़ने के लिए उस पर टैप करें। (आप उन्हें कभी भी दोबारा खोल सकते हैं।)","sect.locks":"🔒 ताले","sect.locksHint":"ऊपर दिए गए सबूतों की मदद से ही हर ताला खोलें।","crumb.teacher":"‹ शिक्षक लॉन्च","crumb.suite":"विज्ञान क्रिटिकल थिंकिंग ब्रेकआउट","ui.reset":"↺ फिर से शुरू करें","ui.check":"जाँचें","ui.gotit":"समझ गया","ui.playagain":"फिर से खेलें","ui.solved":"🔓 खुल गया!","ui.pcount":"{total} में से {n} ताले खुले","ui.wordph":"अपना उत्तर लिखें","ui.clear":"मिटाएँ","fb.digit":"यह संख्या सबूतों से मेल नहीं खाती। फिर से जाँचें।","fb.word":"जो शब्द सही बैठता है, उसके लिए सबूतों को देखें।","fb.mc":"यह सबूतों से पुष्ट नहीं होता। फिर से देखें।","fb.multiExtra":"एक चुनाव मज़बूत सबूत नहीं है। मज़बूत का मतलब वे तथ्य हैं जो सबूत वाकई बलों के बारे में सिद्ध करते हैं।","fb.multiMissing":"आप एक मज़बूत सबूत छोड़ रहे हैं। उन सभी को खोजें।","fb.seq":"यह क्रम इस बात से मेल नहीं खाता कि ऊर्जा कैसे स्थानांतरित होती है। फिर से कोशिश करें।","footer.privacy":"गोपनीयता और अनुपालन","footer.disclaimer":"2021 टेक्सास एसेंशियल नॉलेज एंड स्किल्स फ़ॉर साइंस (§112.26, कक्षा 6) के अनुरूप। सद्भावनापूर्ण भावानुवाद; अपनाने से पहले पुष्टि करें।","header.eyebrow":"विज्ञान क्रिटिकल थिंकिंग ब्रेकआउट · कक्षा 6","header.h1":"मालवाहक जहाज़ का बचाव","header.sub":"मालवाहक जहाज़ TEKS Voyager ह्यूस्टन बंदरगाह पर फँसा हुआ है। वह ख़तरनाक रूप से नीचे झुक रहा है, डेक पर रखा एक क्रेट बार-बार फिसल रहा है, और लोडिंग क्रेन की ऊर्जा घट रही है। आप बंदरगाह इंजीनियर हैं। सबूत पढ़ें, चारों ताले खोलें, और जहाज़ को रवाना होने की अनुमति दें।","brief.label":"⚓ मिशन ब्रीफ़","brief.h":"Voyager को रवाना होने की अनुमति दें","brief.p":"डॉक पर्यवेक्षक आपको रेडियो पर बताते हैं: <b>“वह लगातार नीचे धँसती जा रही है, एक क्रेट डेक पर फिसल गया, और क्रेन की बिजली बंद हो गई।”</b> हर समस्या के पीछे एक वैज्ञानिक कारण सबूतों में छिपा है — घनत्व, बल, और ऊर्जा। हर सबूत खोलें, तौलें कि वह वाकई क्या सिद्ध करता है, और चारों ताले खोलकर Voyager को सुरक्षित समुद्र में भेजें।","footer.text":"विज्ञान क्रिटिकल थिंकिंग ब्रेकआउट · पूरी तरह आपके ब्राउज़र में चलता है — कोई लॉगिन नहीं, कोई डेटा एकत्र नहीं किया जाता।","win.stamp":"रवाना होने की अनुमति ✓","win.h":"Voyager रवाना हो गई!","win.p":"आपने घनत्व से समझाया कि एक स्टील का जहाज़ क्यों तैरता है, सिद्ध किया कि क्रेट पर लगने वाले बल संतुलित थे, न्यूटन के तीसरे नियम का नाम बताया, और क्रेन की ऊर्जा को एक भी जूल खोए बिना उसकी राह पर आगे बढ़ाया। असली जहाज़ों को सुरक्षित रखने के लिए समुद्री इंजीनियर ठीक यही करते हैं।"},"CONTENT":{"clues":[{"id":"c1","ico":"⚖️","nm":"घनत्व तय करता है","title":"घनत्व तय करता है कि कौन तैरेगा","body":"घनत्व = द्रव्यमान ÷ आयतन। कोई वस्तु किसी तरल में तब तैरती है जब उसका <b>कुल</b> घनत्व तरल के घनत्व से <b>कम</b> होता है। स्टील पानी से कहीं अधिक घना है — स्टील की एक ठोस छड़ डूब जाती है। लेकिन जहाज़ का खोखला पतवार उसी द्रव्यमान को एक विशाल आयतन में फैला देता है, जिससे जहाज़ का कुल घनत्व पानी के घनत्व से नीचे गिर जाता है, और वह तैरने लगता है।"},{"id":"c2","ico":"🚢","nm":"बहुत नीचे झुकना","title":"Voyager क्यों नीचे झुक रही है","body":"लादे गए हर क्रेट से <b>द्रव्यमान</b> बढ़ता है पर पतवार का <b>आयतन</b> नहीं। उसी आयतन में अधिक द्रव्यमान जहाज़ के कुल घनत्व को पानी के घनत्व की ओर ऊपर धकेलता है। रंगी हुई भार-रेखा से आगे लादो तो कुल घनत्व पानी के घनत्व को पार कर जाता है — तब जहाज़ तैरना बंद कर देता है और डूबने लगता है।"},{"id":"c3","ico":"🧲","nm":"फिसलता क्रेट","title":"वह क्रेट जो फिसल गया","body":"एक क्रेट समतल डेक पर रखा है। गुरुत्वाकर्षण उसे नीचे खींचता है; डेक का <b>अभिलंब बल</b> बराबर मात्रा में ऊपर धकेलता है; <b>घर्षण</b> उसे हल्के धक्के के विरुद्ध थामे रखता है। जब क्रेट पर लगने वाले सभी बलों का योग <b>शून्य</b> हो जाता है, तो कुल (परिणामी) बल शून्य होता है और उसकी गति नहीं बदलती — यही <b>संतुलित</b> कहलाता है। एक लहर एक अतिरिक्त पार्श्व धक्का जोड़ती है, परिणामी बल अब शून्य नहीं रहता, और क्रेट फिसल जाता है।"},{"id":"c4","ico":"🔁","nm":"पीछे धकेलना","title":"प्रोपेलर का धक्का","body":"न्यूटन का <b>तीसरा नियम</b>: हर बल के लिए <b>दूसरी</b> वस्तु पर एक बराबर और विपरीत बल होता है। प्रोपेलर पानी को <b>पीछे</b> धकेलता है; पानी जहाज़ को <b>आगे</b> धकेलता है। दोनों बल मात्रा में बराबर और दिशा में विपरीत हैं, पर वे <b>अलग-अलग वस्तुओं</b> पर लगते हैं, इसलिए वे एक-दूसरे को रद्द नहीं करते — और जहाज़ आगे बढ़ता है।"},{"id":"c5","ico":"⚡","nm":"क्रेन की ऊर्जा","title":"क्रेन की ऊर्जा कहाँ जाती है","body":"क्रेन डॉक से आने वाली <b>विद्युत ऊर्जा</b> पर चलती है। यह एक क्रेट को ऊँचा उठाती है, जिससे <b>गुरुत्वीय स्थितिज ऊर्जा</b> संचित होती है। जब क्रेट को नीचे उतारा जाता है, तो वह संचित ऊर्जा गति की <b>गतिज ऊर्जा</b> में बदल जाती है। ऊर्जा कभी न तो बनाई जाती है और न ही नष्ट होती है — यह केवल स्थानांतरित होती है और रूप बदलती है। इसे क्रम में पहचानो और कोई भी गायब नहीं होती।"},{"id":"c6","ico":"🐙","nm":"गोताखोर का तथ्य","title":"एक बंदरगाह गोताखोर का पसंदीदा तथ्य","body":"विशाल प्रशांत ऑक्टोपस के <b>तीन दिल</b> होते हैं और नीला, ताँबे पर आधारित ख़ून होता है, और यह अपनी चोंच से बड़े किसी भी छेद से निकल सकता है। बंदरगाह के गोताखोरों को खंभों के पास इसे देखना बहुत पसंद है। यह एक सच्चा और अद्भुत तथ्य है — पर यह आपको Voyager को लादने या रवाना करने के बारे में कुछ नहीं बताता।"}],"locks":[{"id":"L1","type":"seq","color":"#f0a316","title":"क्रेन की ऊर्जा की राह पर चलें","q":"क्रेन जब एक क्रेट को उठाती है और फिर नीचे उतारती है, तो उसकी ऊर्जा जिस क्रम में बदलती है उसमें रखें। पैड को क्रम में टैप करें।","pads":[{"k":"pot","e":"⬆️ स्थितिज","c":"#1aa3b8"},{"k":"elec","e":"🔌 विद्युत","c":"#f0a316"},{"k":"kin","e":"⬇️ गतिज","c":"#2f6fe0"}],"answer":["elec","pot","kin"],"reason":"विद्युत ऊर्जा क्रेट को उठाती है (स्थितिज ऊर्जा संचित करते हुए), फिर उसे नीचे उतारने पर गतिज ऊर्जा निकलती है। ऊर्जा स्थानांतरण को क्रम में पहचानने से पता चलता है कि ऊर्जा संरक्षित रहती है, खोती नहीं।"},{"id":"L2","type":"mc","color":"#0a6b52","title":"स्टील का जहाज़ क्यों तैरता है","q":"स्टील की एक ठोस छड़ डूब जाती है, फिर भी स्टील की Voyager तैरती है। सबूत किस व्याख्या का समर्थन करते हैं?","options":["जहाज़ बस छड़ से हल्का है।","खोखला पतवार जहाज़ के द्रव्यमान को एक बड़े आयतन में फैला देता है, इसलिए उसका कुल घनत्व पानी के घनत्व से कम है।","पानी छोटी वस्तुओं की तुलना में बड़ी वस्तुओं पर ज़्यादा ज़ोर से धकेलता है।"],"answerIndex":1,"reason":"घनत्व द्रव्यमान की तुलना आयतन से करता है। स्टील को खोखले पतवार का आकार देने से उसका आयतन बढ़ता है, जिससे कुल घनत्व पानी के घनत्व से नीचे आ जाता है — और यही उसे तैराता है।"},{"id":"L3","type":"multi","color":"#2f6fe0","title":"संतुलित या नहीं?","q":"लहर के टकराने से पहले, क्रेट बिल्कुल स्थिर बैठा था। केवल वे मज़बूत सबूत चुनें जो बताते हैं कि क्रेट पर लगने वाले बल संतुलित थे (परिणामी बल = शून्य)। जो तथ्य सच है पर विषय से हटकर है उसे छोड़ दें।","items":[{"t":"नीचे खींचता गुरुत्वाकर्षण और ऊपर धकेलता डेक का अभिलंब बल मात्रा में बराबर हैं।","strong":true},{"t":"घर्षण एक हल्के पार्श्व धक्के को रद्द कर देता है, इसलिए क्रेट हिलता नहीं।","strong":true},{"t":"क्रेट स्थिर रहता है — उसकी गति नहीं बदल रही।","strong":true},{"t":"एक विशाल प्रशांत ऑक्टोपस के तीन दिल और नीला ख़ून होता है।","strong":false}],"reason":"संतुलित बलों का योग शून्य होता है, इसलिए किसी वस्तु की गति नहीं बदलती। मज़बूत सबूत केवल वही है जो दिखाता है कि परिणामी बल शून्य है — ऑक्टोपस वाला तथ्य सच है पर असंगत है।"},{"id":"L4","type":"word","color":"#e0533a","title":"नियम का नाम बताएँ","q":"प्रोपेलर पानी को पीछे धकेलता है और पानी जहाज़ को आगे धकेलता है — बराबर मात्रा, विपरीत दिशा, अलग-अलग वस्तुओं पर। यह न्यूटन का कौन-सा नियम है? संख्या को शब्द में लिखें (उदाहरण के लिए, “पहला”)।","answer":["तीसरा","तीसरा नियम","न्यूटन का तीसरा नियम","न्यूटन का तीसरा","क्रिया-प्रतिक्रिया","क्रिया प्रतिक्रिया","third","3rd","newton's third","newtons third","third law","newton's third law","action-reaction","action reaction","tercera"],"reason":"यह न्यूटन का तीसरा नियम है। तीसरे नियम के बल-युग्म बराबर और विपरीत होते हैं पर अलग-अलग वस्तुओं पर लगते हैं, इसलिए वे कभी रद्द नहीं होते — और ठीक इसीलिए जहाज़ आगे बढ़ता है।"}]}},"ur":{"UI":{"sect.clues":"🔍 شواہد","sect.cluesHint":"ہر شہادت کو پڑھنے کے لیے اُس پر ٹیپ کریں۔ (آپ اُنہیں کسی بھی وقت دوبارہ کھول سکتے ہیں۔)","sect.locks":"🔒 تالے","sect.locksHint":"ہر تالے کو صرف اوپر دیے گئے شواہد کی مدد سے کھولیں۔","crumb.teacher":"‹ اساتذہ کا آغاز","crumb.suite":"سائنس تنقیدی سوچ بریک آؤٹس","ui.reset":"↺ دوبارہ شروع","ui.check":"جانچیں","ui.gotit":"سمجھ گیا","ui.playagain":"دوبارہ کھیلیں","ui.solved":"🔓 کھل گیا!","ui.pcount":"{total} میں سے {n} تالے کھلے","ui.wordph":"اپنا جواب لکھیں","ui.clear":"صاف کریں","fb.digit":"یہ عدد شواہد سے میل نہیں کھاتا۔ دوبارہ جانچیں۔","fb.word":"اُس لفظ کے لیے شواہد دیکھیں جو موزوں ہے۔","fb.mc":"اِس کی تائید شواہد سے نہیں ہوتی۔ دوبارہ دیکھیں۔","fb.multiExtra":"ایک انتخاب مضبوط شہادت نہیں ہے۔ مضبوط کا مطلب وہ حقائق ہیں جو شواہد واقعی قوتوں کے بارے میں ثابت کرتے ہیں۔","fb.multiMissing":"آپ سے مضبوط شہادت کا ایک ٹکڑا رہ گیا ہے۔ سب تلاش کریں۔","fb.seq":"یہ ترتیب اِس سے میل نہیں کھاتی کہ توانائی کیسے منتقل ہوتی ہے۔ دوبارہ کوشش کریں۔","footer.privacy":"رازداری اور تعمیل","footer.disclaimer":"2021 کے ٹیکساس کے سائنس کے لازمی علم و مہارت (§112.26، گریڈ ۶) سے ہم آہنگ۔ نیک نیتی پر مبنی ترجمانی؛ اپنانے سے پہلے تصدیق کریں۔","header.eyebrow":"سائنس تنقیدی سوچ بریک آؤٹ · گریڈ ۶","header.h1":"کارگو بحری جہاز کی بچاؤ مہم","header.sub":"مال بردار جہاز TEKS Voyager ہیوسٹن کی بندرگاہ پر پھنسا ہوا ہے۔ یہ خطرناک حد تک نیچے دھنسا ہوا ہے، ڈیک پر رکھا ایک صندوق بار بار سرک رہا ہے، اور لوڈنگ کرین کی طاقت ختم ہو رہی ہے۔ آپ بندرگاہ کے انجینئر ہیں۔ شواہد پڑھیں، چاروں تالے کھولیں، اور جہاز کو روانہ ہونے کی اجازت دیں۔","brief.label":"⚓ مشن کی تفصیل","brief.h":"Voyager کو روانگی کے لیے تیار کریں","brief.p":"گودی کا نگران آپ کو ریڈیو پر بتاتا ہے: <b>”یہ دھنسنا بند نہیں کر رہا، ایک صندوق ڈیک پر سرک گیا، اور کرین ٹرِپ ہو گئی۔“</b> ہر مسئلے کے پیچھے ایک سائنسی وجہ شواہد میں چھپی ہے — کثافت، قوتیں، اور توانائی۔ ہر شہادت کھولیں، تولیں کہ وہ واقعی کیا ثابت کرتی ہے، اور Voyager کو محفوظ طریقے سے سمندر بھیجنے کے لیے چاروں تالے کھولیں۔","footer.text":"سائنس تنقیدی سوچ بریک آؤٹس · مکمل طور پر آپ کے براؤزر میں چلتا ہے — نہ کوئی لاگ اِن، نہ کوئی ڈیٹا جمع کیا جاتا ہے۔","win.stamp":"روانگی کی اجازت ✓","win.h":"Voyager روانہ ہو گیا!","win.p":"آپ نے کثافت سے سمجھایا کہ فولادی جہاز کیوں تیرتا ہے، ثابت کیا کہ صندوق پر قوتیں متوازن تھیں، نیوٹن کے تیسرے قانون کا نام لیا، اور کرین کی توانائی کو ایک جُول ضائع کیے بغیر ٹریس کیا۔ بحری انجینئر بالکل اسی طرح حقیقی جہازوں کو محفوظ رکھتے ہیں۔"},"CONTENT":{"clues":[{"id":"c1","ico":"⚖️","nm":"کثافت فیصلہ کرتی ہے","title":"کثافت طے کرتی ہے کہ کون تیرے گا","body":"کثافت = کمیت ÷ حجم۔ کوئی چیز کسی سیال میں تب تیرتی ہے جب اُس کی <b>مجموعی</b> کثافت سیال کی کثافت سے <b>کم</b> ہو۔ فولاد پانی سے کہیں زیادہ کثیف ہے — ٹھوس فولادی سلاخ ڈوب جاتی ہے۔ لیکن جہاز کا کھوکھلا ڈھانچہ اُسی کمیت کو ایک بہت بڑے حجم میں پھیلا دیتا ہے، تو جہاز کی مجموعی کثافت پانی سے کم ہو جاتی ہے، اور یہ تیرنے لگتا ہے۔"},{"id":"c2","ico":"🚢","nm":"بہت نیچے دھنسنا","title":"Voyager کیوں نیچے دھنسا ہوا ہے","body":"لادا جانے والا ہر صندوق <b>کمیت</b> بڑھاتا ہے مگر ڈھانچے کا <b>حجم</b> نہیں۔ اُسی حجم میں زیادہ کمیت جہاز کی مجموعی کثافت کو پانی کی کثافت کی طرف دھکیلتی ہے۔ رنگ سے بنی لوڈ لائن سے زیادہ لادیں تو مجموعی کثافت پانی سے بڑھ جاتی ہے — پھر جہاز تیرنا چھوڑ کر ڈوبنے لگتا ہے۔"},{"id":"c3","ico":"🧲","nm":"سرکتا صندوق","title":"وہ صندوق جو سرک گیا","body":"ایک صندوق ہموار ڈیک پر رکھا ہے۔ کششِ ثقل اُسے نیچے کھینچتی ہے؛ ڈیک کی <b>عمودی قوت</b> برابر مقدار سے اوپر دھکیلتی ہے؛ <b>رگڑ</b> اُسے ہلکے دھکے کے مقابلے میں تھامے رکھتی ہے۔ جب صندوق پر لگنے والی تمام قوتوں کا مجموعہ <b>صفر</b> ہو، تو خالص قوت صفر ہوتی ہے اور اُس کی حرکت نہیں بدلتی — یہی <b>متوازن</b> ہونا ہے۔ ایک لہر ایک اضافی طرفی دھکا دیتی ہے، خالص قوت اب صفر نہیں رہتی، اور صندوق سرک جاتا ہے۔"},{"id":"c4","ico":"🔁","nm":"پیچھے دھکیلنا","title":"پروپیلر کا دھکا","body":"نیوٹن کا <b>تیسرا قانون</b>: ہر قوت کے لیے <b>دوسری</b> شے پر ایک برابر اور مخالف قوت ہوتی ہے۔ پروپیلر پانی کو <b>پیچھے</b> دھکیلتا ہے؛ پانی جہاز کو <b>آگے</b> دھکیلتا ہے۔ دونوں قوتیں مقدار میں برابر اور سمت میں مخالف ہیں، مگر یہ <b>مختلف اشیاء</b> پر عمل کرتی ہیں، اِس لیے ایک دوسرے کو ختم نہیں کرتیں — اور جہاز آگے بڑھتا ہے۔"},{"id":"c5","ico":"⚡","nm":"کرین کی توانائی","title":"کرین کی توانائی کہاں جاتی ہے","body":"کرین گودی سے آنے والی <b>برقی توانائی</b> پر چلتی ہے۔ یہ صندوق کو اونچا اٹھاتی ہے، اور <b>ثقلی وضعی توانائی</b> ذخیرہ کرتی ہے۔ جب صندوق نیچے اتارا جاتا ہے، وہ ذخیرہ شدہ توانائی حرکت کی <b>حرکی توانائی</b> میں بدل جاتی ہے۔ توانائی نہ کبھی پیدا ہوتی ہے نہ فنا — یہ صرف منتقل ہوتی اور شکل بدلتی ہے۔ اِسے ترتیب سے ٹریس کریں اور کچھ بھی ضائع نہیں ہوتا۔"},{"id":"c6","ico":"🐙","nm":"غوطہ خور کی بات","title":"بندرگاہ کے غوطہ خور کی پسندیدہ بات","body":"دیو ہیکل بحرالکاہل کے آکٹوپس کے <b>تین دل</b> اور تانبے پر مبنی نیلا خون ہوتا ہے، اور یہ اپنی چونچ سے بڑے کسی بھی سوراخ سے نکل سکتا ہے۔ بندرگاہ کے غوطہ خور اِسے کھمبوں کے پاس دیکھنا پسند کرتے ہیں۔ یہ ایک سچی اور حیرت انگیز بات ہے — مگر یہ Voyager کو لادنے یا چلانے کے بارے میں کچھ نہیں بتاتی۔"}],"locks":[{"id":"L1","type":"seq","color":"#f0a316","title":"کرین کی توانائی کا پیچھا کریں","q":"کرین کی توانائی کو اُس ترتیب میں رکھیں جس میں یہ صندوق اٹھاتے اور پھر نیچے اتارتے وقت بدلتی ہے۔ پیڈز کو ترتیب سے ٹیپ کریں۔","pads":[{"k":"pot","e":"⬆️ وضعی","c":"#1aa3b8"},{"k":"elec","e":"🔌 برقی","c":"#f0a316"},{"k":"kin","e":"⬇️ حرکی","c":"#2f6fe0"}],"answer":["elec","pot","kin"],"reason":"برقی توانائی صندوق کو اٹھاتی ہے (وضعی توانائی ذخیرہ کرتے ہوئے)، پھر اُسے نیچے اتارنا حرکی توانائی خارج کرتا ہے۔ توانائی کی منتقلی کو ترتیب سے ٹریس کرنا دکھاتا ہے کہ توانائی محفوظ رہتی ہے، ضائع نہیں ہوتی۔"},{"id":"L2","type":"mc","color":"#0a6b52","title":"فولادی جہاز کیوں تیرتا ہے","q":"ٹھوس فولادی سلاخ ڈوب جاتی ہے، پھر بھی فولادی Voyager تیرتا ہے۔ شواہد کس وضاحت کی تائید کرتے ہیں؟","options":["جہاز محض سلاخ سے ہلکا ہے۔","کھوکھلا ڈھانچہ جہاز کی کمیت کو بڑے حجم میں پھیلاتا ہے، تو اُس کی مجموعی کثافت پانی سے کم ہو جاتی ہے۔","پانی بڑی اشیاء پر چھوٹی اشیاء سے زیادہ زور سے دھکیلتا ہے۔"],"answerIndex":1,"reason":"کثافت کمیت کا حجم سے موازنہ کرتی ہے۔ فولاد کو کھوکھلے ڈھانچے میں ڈھالنا اُس کا حجم بڑھاتا ہے، جو مجموعی کثافت کو پانی سے کم کر دیتا ہے — اور یہی اُسے تیرنے کے قابل بناتا ہے۔"},{"id":"L3","type":"multi","color":"#2f6fe0","title":"متوازن یا نہیں؟","q":"لہر کے ٹکرانے سے پہلے صندوق بالکل ساکن رکھا تھا۔ صرف وہ مضبوط شواہد منتخب کریں جو دکھاتے ہیں کہ صندوق پر قوتیں متوازن تھیں (خالص قوت = صفر)۔ سچی مگر غیر متعلق بات چھوڑ دیں۔","items":[{"t":"کششِ ثقل کا نیچے کھینچنا اور ڈیک کی عمودی قوت کا اوپر دھکیلنا مقدار میں برابر ہیں۔","strong":true},{"t":"رگڑ ہلکے طرفی دھکے کو ختم کر دیتی ہے، اِس لیے صندوق نہیں ہلتا۔","strong":true},{"t":"صندوق ساکن رہتا ہے — اُس کی حرکت نہیں بدل رہی۔","strong":true},{"t":"دیو ہیکل بحرالکاہل کے آکٹوپس کے تین دل اور نیلا خون ہوتا ہے۔","strong":false}],"reason":"متوازن قوتوں کا مجموعہ صفر ہوتا ہے، اِس لیے کسی چیز کی حرکت نہیں بدلتی۔ مضبوط شہادت صرف وہی ہے جو دکھائے کہ خالص قوت صفر ہے — آکٹوپس والی بات سچی مگر غیر متعلق ہے۔"},{"id":"L4","type":"word","color":"#e0533a","title":"قانون کا نام بتائیں","q":"پروپیلر پانی کو پیچھے دھکیلتا ہے اور پانی جہاز کو آگے دھکیلتا ہے — برابر مقدار، مخالف سمت، مختلف اشیاء پر۔ یہ نیوٹن کا کون سا قانون ہے؟ عدد کا لفظ لکھیں (مثلاً ”پہلا“)۔","answer":["تیسرا","تیسرا قانون","نیوٹن کا تیسرا","نیوٹن کا تیسرا قانون","عمل ردعمل","عمل اور ردعمل","third","3rd","newton's third","newtons third","third law","newton's third law","action-reaction","action reaction","tercera"],"reason":"یہ نیوٹن کا تیسرا قانون ہے۔ تیسرے قانون کی قوتیں برابر اور مخالف ہوتی ہیں مگر مختلف اشیاء پر عمل کرتی ہیں، اِس لیے کبھی ایک دوسرے کو ختم نہیں کرتیں — اور بالکل اِسی لیے جہاز آگے بڑھتا ہے۔"}]}},"zh":{"UI":{"sect.clues":"🔍 证据","sect.cluesHint":"点一下每条证据来阅读。你随时都可以再打开它们。","sect.locks":"🔒 密码锁","sect.locksHint":"只用上面的证据来打开每一把锁。","crumb.teacher":"‹ 教师启动页","crumb.suite":"科学批判性思维破解游戏","ui.reset":"↺ 重新开始","ui.check":"检查","ui.gotit":"明白了","ui.playagain":"再玩一次","ui.solved":"🔓 打开了！","ui.pcount":"已打开 {n} / {total} 把锁","ui.wordph":"输入你的答案","ui.clear":"清除","fb.digit":"这个数字和证据对不上。再检查一下。","fb.word":"在证据里找一找合适的词。","fb.mc":"证据并不支持这个答案。再看看吧。","fb.multiExtra":"有一项不是有力的证据。有力的证据是指证据真正证明了的、关于这些力的事实。","fb.multiMissing":"你还漏了一条有力的证据。把它们全都找出来。","fb.seq":"这个顺序和能量传递的方式对不上。再试一次。","footer.privacy":"隐私与合规","footer.disclaimer":"对照 2021 年德州科学基础知识与技能标准（§112.26，六年级）。善意改写；采用前请自行核实。","header.eyebrow":"科学批判性思维破解游戏 · 六年级","header.h1":"货轮救援","header.sub":"货轮「TEKS 号」被卡在了休斯敦港。它吃水低得危险，甲板上的货箱不停打滑，装卸起重机也在漏电。你是港口工程师。阅读证据，打开全部四把锁，让这艘船获准出航。","brief.label":"⚓ 任务简报","brief.h":"让「TEKS 号」获准出航","brief.p":"码头主管用无线电呼叫你：<b>「它一直往下沉，一只货箱在甲板上滑走了，起重机也跳闸了。」</b>每个问题背后都藏着一个科学原因，就在证据里——密度、力和能量。打开每一条证据，掂量它到底证明了什么，打开全部四把锁，让「TEKS 号」平安出海。","footer.text":"科学批判性思维破解游戏 · 完全在你的浏览器里运行——无需登录，不收集任何数据。","win.stamp":"获准出航 ✓","win.h":"「TEKS 号」出航了！","win.p":"你用密度解释了钢制的船为什么能浮起来，证明了货箱受到的力是平衡的，说出了牛顿第三定律，还追踪了起重机的能量而没有丢失一焦耳。船舶工程师正是这样让真实的船只保持安全的。"},"CONTENT":{"clues":[{"id":"c1","ico":"⚖️","nm":"密度说了算","title":"密度决定谁能浮","body":"密度 = 质量 ÷ 体积。当一个物体的<b>整体</b>密度<b>小于</b>流体的密度时，它就会在流体里浮起来。钢的密度比水大得多——一根实心钢条会沉下去。但一艘船中空的船身把同样的质量分散到很大的体积里，于是船的整体密度降到了水以下，船就浮起来了。"},{"id":"c2","ico":"🚢","nm":"吃水太低","title":"「TEKS 号」为什么吃水这么低","body":"每装上一只货箱，都会增加<b>质量</b>，却不会增加船身的<b>体积</b>。同样的体积里质量更多，就把船的整体密度往水的密度推。装货超过船身上漆的载重线，整体密度就会超过水——这时船就不再浮起，而是开始下沉。"},{"id":"c3","ico":"🧲","nm":"打滑的货箱","title":"滑走的那只货箱","body":"一只货箱放在平坦的甲板上。重力把它往下拉；甲板的<b>支持力</b>以同样大小把它往上推；<b>摩擦力</b>顶住轻轻的推动。当货箱受到的所有力加起来等于<b>零</b>时，合力就是零，它的运动状态不会改变——这就是<b>平衡</b>。一个浪头额外多加了一个侧向的推力，合力不再是零，货箱就滑走了。"},{"id":"c4","ico":"🔁","nm":"反推","title":"螺旋桨的推力","body":"牛顿<b>第三定律</b>：每一个力，都会在<b>另一个</b>物体上产生一个大小相等、方向相反的力。螺旋桨把水往<b>后</b>推；水就把船往<b>前</b>推。这两个力大小相等、方向相反，但作用在<b>不同的物体</b>上，所以不会相互抵消——于是船就前进了。"},{"id":"c5","ico":"⚡","nm":"起重机的能量","title":"起重机的能量去了哪里","body":"起重机靠码头供给的<b>电能</b>运转。它把一只货箱高高吊起，储存了<b>重力势能</b>。当货箱被放下时，储存的能量又转化成运动的<b>动能</b>。能量既不会凭空产生，也不会凭空消失——它只是传递和改变形式。按顺序追踪它，一点都不会丢失。"},{"id":"c6","ico":"🐙","nm":"潜水员的趣事","title":"港口潜水员最爱的一个冷知识","body":"北太平洋巨型章鱼有<b>三个心脏</b>，血液是蓝色的、以铜为基础，还能钻过任何比它的喙更大的缝隙。港口的潜水员很喜欢在桩柱附近发现它。这是一个真实又神奇的事实——但它对于装载或驾驶「TEKS 号」没有任何帮助。"}],"locks":[{"id":"L1","type":"seq","color":"#f0a316","title":"追踪起重机的能量","q":"按照起重机吊起再放下货箱时能量转化的顺序，把它们排好。依次点一下这些按钮。","pads":[{"k":"pot","e":"⬆️ 势能","c":"#1aa3b8"},{"k":"elec","e":"🔌 电能","c":"#f0a316"},{"k":"kin","e":"⬇️ 动能","c":"#2f6fe0"}],"answer":["elec","pot","kin"],"reason":"电能把货箱吊起（储存了势能），然后放下时释放出动能。按顺序追踪能量的传递，说明能量是守恒的，并没有丢失。"},{"id":"L2","type":"mc","color":"#0a6b52","title":"钢制的船为什么能浮","q":"一根实心钢条会沉下去，可钢制的「TEKS 号」却能浮起来。证据支持哪一种解释？","options":["这艘船只是比钢条轻。","中空的船身把船的质量分散到很大的体积里，所以它的整体密度小于水的密度。","水对大物体的推力比对小物体的更大。"],"answerIndex":1,"reason":"密度是把质量和体积作比较。把钢造成中空的船身增大了体积，从而使整体密度降到水以下——正是这一点让它浮了起来。"},{"id":"L3","type":"multi","color":"#2f6fe0","title":"平衡还是不平衡？","q":"在浪头打来之前，货箱一动不动地立在那里。只勾选能有力证明货箱受到的力是「平衡」（合力 = 零）的证据。把那条真实却离题的事实排除在外。","items":[{"t":"向下拉的重力和甲板向上推的支持力大小相等。","strong":true},{"t":"摩擦力抵消了轻轻的侧向推动，所以货箱纹丝不动。","strong":true},{"t":"货箱保持静止——它的运动状态没有改变。","strong":true},{"t":"北太平洋巨型章鱼有三个心脏和蓝色的血液。","strong":false}],"reason":"平衡的力加起来等于零，所以物体的运动状态不会改变。有力的证据只包括能表明合力为零的内容——章鱼那条事实虽然是真的，却毫不相关。"},{"id":"L4","type":"word","color":"#e0533a","title":"说出这条定律","q":"螺旋桨把水往后推，水把船往前推——大小相等、方向相反、作用在不同的物体上。这是牛顿的哪一条定律？请输入序数词（例如「第一」）。","answer":["第三","牛顿第三定律","第三定律","牛顿第三","作用力与反作用力","作用与反作用","third","3rd","newton's third","newtons third","third law","newton's third law","action-reaction","action reaction","tercera"],"reason":"这是牛顿第三定律。第三定律里成对的力大小相等、方向相反，但作用在不同的物体上，所以永远不会相互抵消——这正是船能前进的原因。"}]}}};for(var L in T){B.UI[L]=T[L].UI;B.CONTENT[L]=T[L].CONTENT;}})();
